sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    var sysId = api.data.glide_form_item.nowActivityStreamComposeConnected.sysId;
    if (sysId && sysId != -1) {
        api.emit("RECORD_CREATED", {});
        helpers.modal.close();
        if (api.context.props.parentTable == 'sn_risk_mitigation_task') {
            api.emit("RECORD#_RELATED_LIST_REFRESH_REQUESTED_RELAY_21fcdb090f572010878cddcd58767e27", {
                relatedListName: "sn_risk_m2m_risk_mitigation_control.risk_mitigation"
            });
        } else if (api.context.props.parentTable == 'sn_risk_advanced_risk_assessment_project') {
            api.emit("REFRESH_LIST",{});
        }
    }
}
